import hashlib

def h(pw):
    return hashlib.sha256(pw.encode("utf-8")).hexdigest()

class User:
    def __init__(self, name, pw):
        self.name = name
        self.pw_hash = h(pw)
        self.fails = 0

    def check(self, pw):
        if self.fails >= 3:
            raise PermissionError("locked")
        if h(pw) == self.pw_hash:
            self.fails = 0
            return True
        self.fails = self.fails + 1
        return False

class UserStore:
    def __init__(self):
        self.users = {}

    def add(self, name, pw):
        if name in self.users:
            raise ValueError("exists")
        self.users[name] = User(name, pw)

    def login(self, name, pw):
        return self.users[name].check(pw)

store = UserStore()
while True:
    parts = input().split()
    if parts[0] == "exit":
        break
    try:
        if parts[0] == "add":
            store.add(parts[1], parts[2])
            print("added")
        elif parts[0] == "login":
            print("ok" if store.login(parts[1], parts[2]) else "bad")
    except ValueError as e:
        print("error", e)
    except KeyError:
        print("no user")
    except PermissionError as e:
        print(e)

