import hashlib

def h(pw):
    return hashlib.sha256(pw.encode("utf-8")).hexdigest()

class User:
    def __init__(self, name, pw):
        self.name = name
        self.pw_hash = h(pw)
        self.fails = 0

    def check(self, pw):
        if self.fails >= 3:
            raise PermissionError("locked")
        if h(pw) == self.pw_hash:
            self.fails = 0
            return True
        self.fails = self.fails + 1
        return False

class Admin(User):
    def unlock(self, user):
        user.fails = 0

u = User("sara", "pw")
for _ in range(3):
    u.check("x")
try:
    u.check("pw")
except PermissionError:
    print("locked")
admin = Admin("root", "r")
admin.unlock(u)
print(u.check("pw"))
